\label{lem:joint_scalar}
The pair \((\widetilde{T}^n,X^n)\) generated by Algorithm~\ref{alg:grm_scalar}
has the same law as the generative pair \((T^n,X^n)\). In particular,
for every \(i\in\{1,\ldots,n\}\),
    \begin{equation}
\label{eq:joint_scalar}
    X_i\mid(\widetilde{T}_i=k)
    \sim
    \mathcal{N}(\mu_k,\sigma_k^2),
    \qquad
    I(X^n;\widetilde{T}^n)
    =
    n\,I(X;T).
    \end{equation}

Both constructions use the same source letter \(X^n\sim f_X^{\otimes n}\). It remains to
match the kernels \(P_{\widetilde{T}^n\mid X^n}\) and \(P_{T^n\mid X^n}\); the
joints then factor in the same way.

Since each \(\sigma_k^2>0\), one has \(f_X(x)>0\) for all \(x\), so the
weights in Algorithm~\ref{alg:grm_scalar} are well-defined. Bayes' rule
for the generative pair \((T,X)\) gives
\begin{equation}
\label{eq:pk_bayes}
    p_k(x)
    =
    \frac{
    \pi_k\,\mathcal{N}(x;\mu_k,\sigma_k^2)
    }{
    f_X(x)
    }
    =
    P(T=k\mid X=x).
\end{equation}
The simulation step is exact \eqref{eq:stoch_sim}, so
\(x\mapsto\bigl(p_1(x),\ldots,p_K(x)\bigr)\)
\cite{LiElGamal2018,FlamichGunduzREC}.
Thus \(P_{\widetilde{T}\mid X}=P_{T\mid X}\), and therefore
\begin{equation}
\label{eq:joint_factor}
    P_{\widetilde{T},X}
    =
    P_{\widetilde{T}\mid X}\,P_X
    =
    P_{T\mid X}\,P_X
    =
    P_{T,X}.
\end{equation}
In particular, \(P(\widetilde{T}=k)=\pi_k>0\) and
\(X\mid(\widetilde{T}=k)\sim X\mid(T=k)\sim\mathcal{N}(\mu_k,\sigma_k^2)\).
Mutual information depends on a pair only through its joint law, so
\(I(X;\widetilde{T})=I(X;T)\).

\label{thm:grm_scalar}
If \(D<\min_k\sigma_k^2\), then
\begin{equation}
    R_{\mathrm{GRM}}(D)
    =
    h(X)-\tfrac12\log(2\pi e\,D)
    =
    R(D).
\end{equation}

\label{prop:comp_slb}
Fix \(D>0\).
The following are equivalent:
\begin{enumerate}
    \par\hangindent 40\p@ \(R_k(D)=\mathrm{SLB}_k(D)\) for every \(k\);
    \par\hangindent 40\p@ \(R_{\mathrm{GRM}}(D)=\mathrm{SLB}(D)\).
\end{enumerate}
In either case 
\(R_{\mathrm{GRM}}(D)=\mathrm{SLB}(D)=R^{ }(D)\).

\label{cor:grm_asymp}
Assume \(h(\mathbf{X})>-\infty\) and
\begin{equation}
\label{eq:comp_slb_asymp}
    \lim_{D\downarrow 0}
    \bigl(R_k(D)-\mathrm{SLB}_k(D)\bigr)
    =
    0,
    \qquad
    k=1,\ldots,K.
\end{equation}
Then
\begin{equation}
\label{eq:grm_asymp}
    \lim_{D\downarrow 0}
    \bigl(R_{\mathrm{GRM}}(D)-\mathrm{SLB}(D)\bigr)
    =
    \lim_{D\downarrow 0}
    \bigl(R_{\mathrm{GRM}}(D)-R^{ }(D)\bigr)
    =
    0.
\end{equation}

\label{thm:grm}
If
\begin{equation}
    \frac{D}{d}
    <
    \min_{k,m}\lambda_{k,m},
\end{equation}
then

\begin{equation}
    R_{\mathrm{GRM}}(D)
    =
    h(\mathbf{X})
    -
    \frac{d}{2}
    \log\!\bigl(2\pi e\,D/d\bigr)
    =
    R^{ }(D).
\end{equation}
In particular, GRM attains the Shannon RDF throughout this distortion
regime.

\label{lem:RM_limit}
Assume \(\mathbb{E}\|\mathbf{X}\|^2<\infty\). For every integer \(M\ge1\)
and every \(D>0\),
\begin{equation}
\label{eq:RM_mono}
    R^{ }(D)
    \le
    R_{M+1}^{ }(D)
    \le
    R_M^{ }(D),
\end{equation}
with the convention that both sides are \(+\infty\) if the corresponding
constraint set is empty.
Moreover, for every \(D\in(0,D_{\max})\),
\begin{equation}
\label{eq:RM_limit}
    \lim_{M\to\infty}R_M^{ }(D)
    =
    R^{ }(D).
\end{equation}

\label{thm:zero_rate_vec}
Let \(\delta:=D_{\max}-D\).
Then
\begin{equation}
    R^{ }(D_{\max}-\delta)
    =
    \frac{\delta}{2\tau^2}+o(\delta),
    \qquad\delta\downarrow0,
\end{equation}
and the same expansion holds for every \(R_M^{ }(D_{\max}-\delta)\) with
\(M\ge2\).
Moreover,
\begin{equation}
    R^{ }(D)
    \ge
    \frac{D_{\max}-D}{2\tau^2}
\end{equation}
for every \(D\in[0,D_{\max}]\).

\label{cor:gaps}
Let \(M<\infty\) and \(D\in(0,D_{\max})\) satisfy \(R_M^{ }(D)<\infty\).
Then \(R_M^{ }(D)>R^{ }(D)\) in each of the following cases:
\begin{enumerate}
    \par\hangindent 40\p@ \(\mathbf{X}\) is Gaussian;
    \par\hangindent 40\p@ \(R_k(D)=\mathrm{SLB}_k(D)\) for every \(k\), and the
    equality-case reproduction of \eqref{eq:slb} is non-atomic.
\end{enumerate}

\label{lem:floor}
Let \(\mathbf{X}\) be a nondegenerate finite GMM on \(\mathbb{R}^d\) and
let \(M<\infty\). Set
\begin{equation}
    \label{eq:floor_expr}
    D_M^{\star}
    :=
    \inf_{\mathbf{a}_1,\ldots,\mathbf{a}_M\in\mathbb{R}^d}
    \mathbb{E}
    \Bigl[
    \min_{1\le j\le M}
    \|\mathbf{X}-\mathbf{a}_j\|^2
    \Bigr].
\end{equation}
Then
\begin{enumerate}
    \par\hangindent 40\p@ \(D_M^{\star}>0\);
    \par\hangindent 40\p@ \(R_M^{ }(D)=+\infty\) for \(D<D_M^{\star }\);
    \par\hangindent 40\p@ \(R_M^{ }(D_M^{\star })\le\log M\);
    \par\hangindent 40\p@ as \(M\to\infty\),
    \begin{equation}
        \label{eq:zador}
        D_M^{\star }
        \sim
        C_d(\mathbf{X})\,M^{-2/d},
    \end{equation}
    where
    \(C_d(\mathbf{X})
    :=
    G_d
    \int_{\mathbb{R}^d}
    f_{\mathbf{X}}(\mathbf{x})^{d/(d+2)}\,d\mathbf{x}\)
    and \(G_d\in(0,\infty)\) is Zador's constant
    \cite{Zador1982} (\(G_1=1/12\) \cite{PanterDite1951}).
\end{enumerate}
